                                        }`}
                                >
                                    <Eye size={14} />
                                    <span className="text-[9px] font-bold">TEK GÖSTER</span>
                                </button>
                            )}

                            {/* HIDE */}
                            {selectedPart && !isolatedPart && (
                                <button
                                    onClick={handleHide}
                                    className="flex flex-col items-center justify-center gap-0.5 py-1.5 px-1 rounded border bg-white border-gray-200 text-gray-700 hover:bg-gray-50 hover:border-gray-300 transition-all"
                                >
                                    <EyeOff size={14} />
                                    <span className="text-[9px] font-bold">GİZLE</span>
                                </button>
                            )}
                        </div>

                        {/* RECOVERY BUTTONS */}
                        {(isolatedPart || hiddenParts.length > 0) && (
                            <div className="mt-2 pt-2 border-t border-gray-200">
                                <button
                                    onClick={handleShowAll}
                                    className="w-full flex items-center justify-center gap-1.5 py-1 px-2 rounded bg-gray-100 text-gray-700 hover:bg-gray-200 text-[10px] font-bold transition-colors"
                                >
                                    <Layers size={12} />
                                    {isolatedPart ? 'İZOLASYONU KALDIR' : `GİZLENENLERİ GÖSTER (${hiddenParts.length})`}
                                </button>
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    )
}

import type { SupabaseClient } from '@supabase/supabase-js'

export type AdminAuditAction = 'INSERT' | 'UPDATE' | 'DELETE' | 'CUSTOM'

export interface AdminAuditLogInput {
  table_name: string
  row_pk?: string | null
  action: AdminAuditAction
  before?: unknown
  after?: unknown
  comment?: string | null
  actor?: string | null // optional; auto-filled from auth if not provided
}

// Lightweight helper; errors are swallowed on purpose to not block UI
export async function logAdminAction(
  client: SupabaseClient,
  input: AdminAuditLogInput | AdminAuditLogInput[]
): Promise<void> {
  try {
    const rows = Array.isArray(input) ? input : [input]

    // Best-effort: get current user id to set actor if not provided
    let _u_id: string | null = null
    try {
      // Prefer session for reliability; fall back to getUser
      const { data: sessData } = await client.auth.getSession()
      uid = sessData?.session?.user?.id ?? null
      if (!uid) {
        const { data } = await client.auth.getUser()
        uid = data?.user?.id ?? null
      }
    } catch {
      uid = null
    }

    const prepared = rows.map((r) => {
      // Only set actor if not explicitly provided
      const hasActor = Object.prototype.hasOwnProperty.call(r, 'actor') && r.actor != null
      return hasActor ? r : { ...r, actor: uid }
    })

    // Chain .select() to satisfy TS and to ensure request executes immediately
    const { error } = await client.from('admin_audit_log').insert(prepared).select('id')
    if (error) {
      console.warn('audit log insert failed', error)
    }
  } catch (e) {
    console.warn('audit log insert exception', e)
  }
}

